<?php
declare(strict_types=1);require_once __DIR__.'/common.php';require_once __DIR__.'/noa-bridge/storage.php';require_once __DIR__.'/noa-bridge/youtube-store.php';
$admin=!empty($is_member)&&($is_admin??'')==='super';header('Cache-Control: private, no-store');header('X-Content-Type-Options: nosniff');$videos=[];$playlists=[];$run=null;$error=false;
try{$db=noa_bridge_pdo();$run=ny_latest($db);if($run){$videos=ny_videos($db,$run);$q=$db->prepare('SELECT playlist_id,payload FROM noa_youtube_playlists WHERE run_id=?');$q->execute([$run['run_id']]);foreach($q as $p){$value=json_decode($p['payload'],true);if(($value['status']['privacyStatus']??'')==='public')$playlists[$p['playlist_id']]=$value;}}else{
 // Until owner authorization, show existing public music URLs without claiming channel collection.
 $batch=ny_batch($db);foreach(ny_songs($db,$batch) as $s){if(!$s['public_verified'])continue;$id=ny_video_id((string)($s['fields']['youtubeUrl']??''));if(!$id)continue;$videos[$id]=['id'=>$id,'snippet'=>['title'=>$s['fields']['title']??'NOA Music'],'status'=>['privacyStatus'=>'public','embeddable'=>true],'classification'=>'music','legacy'=>true];}
 }}catch(Throwable $e){$error=true;error_log('[noa-youtube-view] '.get_class($e));}
$browseRows=[];$songIndex=[];try{if($run)$songIndex=ny_songs($db,ny_batch($db));}catch(Throwable $e){}
foreach($videos as $id=>$v){if(($v['status']['privacyStatus']??'')!=='public'||empty($v['status']['embeddable'])||isset($_GET['world'])&&($v['classification']??'')!=='official_mv')continue;$song=$songIndex[$v['match']['songId']??'']??null;$browseRows[]=['key'=>$id,'title'=>$v['snippet']['title']??'NOA Music','genre'=>$song['genre_id']??'unclassified','ep'=>$song['ep']??'','act'=>'','kind'=>'video','video'=>$id];}
function nye(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>YouTube | NOA STUDIO</title><link rel="stylesheet" href="/noa-ui.css?v=20261020-quality1"><link rel="stylesheet" href="/noa-ai-lab.css"><link rel="stylesheet" href="/noa-youtube.css"><script src="/noa-ui.js?v=20261020-quality1" defer></script><script src="/noa-browse.js?v=20261021-thumbs1" defer></script><script src="/noa-youtube.js?v=20261021-history1" defer></script><script src="/noa-history.js?v=20261021-history1" defer></script></head><body class="noa-page"><main><p class="noa-eyebrow">NOA STUDIO / WATCH & GROW</p><h1>YouTube</h1><p class="noa-muted">음악에 장면을 더하고, 다음 이야기를 발견하세요.</p><nav class="yt-toolbar"><a href="/noa-music.php">음악</a><a href="/noa-catalog.php">통합 라이브러리</a><a href="/noa-youtube.php">음악 영상</a><a href="/noa-youtube.php?world=1">NOA WORLD · 공식 MV</a><?php if($admin):?><a href="/noa-youtube-admin.php">채널·성장 관리</a><?php endif;?></nav><section id="yt-player" class="lab-panel" hidden><h2 id="yt-playing"></h2><iframe id="yt-frame" title="NOA STUDIO 공식 YouTube 플레이어" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></section><?php if($error):?><p role="status">음악 영상 정보를 읽지 못했습니다. 잠시 후 다시 열어 주세요.</p><?php elseif(!$run):?><p class="noa-muted">기존 음악 라이브러리에 등록된 영상입니다. 채널 소유자 인증 후 전체 채널 수집 결과를 연결합니다.</p><?php endif;?><section id="youtube-browse" class="noa-browse" aria-label="YouTube 탐색"></section><label>전체 영상 검색<input id="youtube-search" type="search" placeholder="제목으로 검색"></label><div class="yt-grid" id="yt-videos"><?php $shown=0;foreach($videos as $id=>$v):if(($v['status']['privacyStatus']??'')!=='public'||empty($v['status']['embeddable']))continue;if(isset($_GET['world'])&&($v['classification']??'')!=='official_mv')continue;$shown++;?><article class="yt-card" data-browse-key="<?=nye($id)?>"><button class="yt-watch" data-video="<?=nye($id)?>" data-title="<?=nye($v['snippet']['title']??'NOA Music')?>" aria-label="<?=nye(($v['snippet']['title']??'NOA Music').' 재생')?>"><img loading="lazy" src="/noa-bridge/youtube-thumbnail.php?id=<?=nye($id)?>" alt=""><span class="yt-play" aria-hidden="true">▶</span></button><h2><?=nye($v['snippet']['title']??'NOA Music')?></h2><p class="noa-muted"><?=($v['classification']??'')==='official_mv'?'NOA WORLD · 공식 MV':'음악 영상'?><?php if(isset($v['statistics']['viewCount'])):?> · 조회 <?=number_format((float)$v['statistics']['viewCount'])?><?php endif;?></p></article><?php endforeach;?></div><?php if(!$shown):?><p>표시할 영상이 없습니다. 공식 MV는 관리자가 확인한 영상부터 표시합니다.</p><?php endif;?><?php if($playlists):?><section class="lab-panel"><h2>YouTube 재생목록</h2><?php foreach($playlists as $pid=>$p):?><p><a href="?playlist=<?=nye($pid)?>"><?=nye($p['snippet']['title']??'재생목록')?></a></p><?php endforeach;?></section><?php endif;?><?php if(isset($_GET['playlist'])&&isset($playlists[$_GET['playlist']])):$q=$db->prepare('SELECT video_id,position FROM noa_youtube_items WHERE run_id=? AND playlist_id=? ORDER BY position,item_id');$q->execute([$run['run_id'],$_GET['playlist']]);?><section class="lab-panel"><h2><?=nye($playlists[$_GET['playlist']]['snippet']['title'])?> · 원본 순서</h2><?php foreach($q as $item):$v=$videos[$item['video_id']]??null;if(!$v||($v['status']['privacyStatus']??'')!=='public')continue;?><p><?=1+(int)$item['position']?>. <button class="yt-text-play" data-video="<?=nye($v['id'])?>" data-title="<?=nye($v['snippet']['title'])?>"><?=nye($v['snippet']['title'])?></button></p><?php endforeach;?></section><?php endif;?></main><script>
window.addEventListener('DOMContentLoaded',()=>{const rows=<?=json_encode($browseRows,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR)?>,search=document.getElementById('youtube-search'),cards=[...document.querySelectorAll('[data-browse-key]')];let browse;const render=()=>{if(!browse)return;const q=search.value.trim().toLowerCase(),base=rows.filter(r=>!q||r.title.toLowerCase().includes(q)),view=browse.apply(base),keys=new Set(view.visible.map(r=>r.key));for(const c of cards)c.hidden=!keys.has(c.dataset.browseKey);document.getElementById('yt-videos').hidden=view.stage!=='songs';};browse=window.NoaBrowse.mount({host:document.getElementById('youtube-browse'),rows,onChange:render,search,kind:'영상'});const focus=rows.find(r=>r.key===new URLSearchParams(location.search).get('track'));if(focus)search.value=focus.title;render();});
</script></body></html>
